package com.assetflow.auth.controller;
import com.assetflow.auth.entity.Company;import com.assetflow.auth.repository.CompanyRepository;import com.assetflow.auth.response.ApiResponse;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/platform/companies") public class PlatformCompanyController {private final CompanyRepository companies;public PlatformCompanyController(CompanyRepository c){companies=c;}private void admin(Authentication a){if(a==null||a.getAuthorities().stream().noneMatch(x->"ROLE_SUPER_ADMIN".equals(x.getAuthority())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Super Admin access is required");}
 @GetMapping public ApiResponse<List<Company>> list(Authentication a){admin(a);return ApiResponse.ok(companies.findAll());}
 @GetMapping("/{id}") public ApiResponse<Company> one(@PathVariable long id,Authentication a){admin(a);return ApiResponse.ok(companies.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Company not found")));}
 @PutMapping("/{id}/status") public ApiResponse<Company> status(@PathVariable long id,@RequestBody Map<String,Object> body,Authentication a){admin(a);Company c=companies.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Company not found"));c.setActive(Boolean.valueOf(String.valueOf(body.getOrDefault("active",true))));return ApiResponse.ok(companies.save(c));}
}
